  [("estrategia", "plan general del equipo para el juego"), ("táctica", "decisión concreta que se toma en el momento para resolver un problema del juego"), ("leer el juego", "mirar el espacio, las reglas y a los compañeros antes de decidir"), ("espacio libre", "zona donde no hay rivales"), ("contrincante", "persona que juega contra ti")],
