  [ex("Un compañero está solo, sin rivales cerca, y otro está marcado de cerca por un rival. ¿A cuál conviene pasarle la pelota?", "Al que está solo", "El que no tiene rivales cerca recibe con más espacio."),
   ex("La regla de tu práctica prohíbe el contacto físico. ¿Una táctica que implica empujar al rival cumple esa regla?", "No", "Empujar es contacto físico y la regla lo prohíbe."),
   ex("«Hoy jugaremos usando todo el ancho de la cancha», ¿es una estrategia o una táctica?", "Una estrategia", "Es un plan general del equipo, no una decisión de un momento.")],
